import javax.swing.*;import java.awt.*;import java.awt.event.*;
public class ConverterAnonymous extends JFrame {JTextField amount=new JTextField(10);JComboBox<String> target=new JComboBox<>(new String[]{"USD","EUR"});JLabel result=new JLabel(" ");ConverterAnonymous(){setLayout(new FlowLayout());JButton b=new JButton("Convert");add(amount);add(target);add(b);add(result);ActionListener h=e->{try{double v=Double.parseDouble(amount.getText().trim());if(!Double.isFinite(v)||v<0)throw new NumberFormatException();result.setText(String.format("%.2f",v*(target.getSelectedItem().equals("USD")?.012:.011)));JOptionPane.showMessageDialog(this,result.getText()+" "+target.getSelectedItem(),"Conversion result",JOptionPane.INFORMATION_MESSAGE);}catch(Exception ex){result.setText("Invalid amount");JOptionPane.showMessageDialog(this,"Invalid amount","Input error",JOptionPane.ERROR_MESSAGE);}};b.addActionListener(h);amount.addActionListener(h);addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){dispose();}});pack();}public static void main(String[]x){SwingUtilities.invokeLater(()->new ConverterAnonymous().setVisible(true));}}
